<?php

/* @autogenerated */
declare(strict_types=1);

use Civi\Lughauth\Features\Access\TenantLoginProvider\Domain\TenantLoginProviderAccountLinkPolicyOptions;
use Civi\Lughauth\Features\Access\TenantLoginProvider\Domain\ValueObject\Accessor\TenantLoginProviderAccountLinkPolicyAccessor;
use PHPUnit\Framework\TestCase;

/**
 * Unit tests for the TenantLoginProviderAccountLinkPolicyAccessor trait.
 *
 * Covers null default, string/VO assignment via withAccountLinkPolicy,
 * getAccountLinkPolicy/accountLinkPolicy accessors, and isAccountLinkPolicyChanged with/without original.
 */
class TenantLoginProviderAccountLinkPolicyAccessorUnitTest extends TestCase
{
    /**
     * Asserts that withAccountLinkPolicy creates a new instance with the AccountLinkPolicy set
     * from a string value, and getAccountLinkPolicy returns the primitive string.
     */
    public function testWithAccountLinkPolicyFromString(): void
    {
        // Arrange
        $holder = new ImplWithTenantLoginProviderAccountLinkPolicyAccessorUnitTest();

        // Act
        $result = $holder->withAccountLinkPolicy(TenantLoginProviderAccountLinkPolicyOptions::NONE);

        // Assert
        $this->assertNotSame($holder, $result);
        $this->assertEquals(TenantLoginProviderAccountLinkPolicyOptions::NONE, $result->getAccountLinkPolicy());
    }
    /**
     * Asserts that withaccountLinkPolicy has access to the value object
     * from a string value, and getAccountLinkPolicy returns the primitive string.
     */
    public function testWithAccountLinkPolicyFromValueObject(): void
    {
        // Arrange
        $holder = new ImplWithTenantLoginProviderAccountLinkPolicyAccessorUnitTest();

        // Act
        $result = $holder->withAccountLinkPolicy(TenantLoginProviderAccountLinkPolicyOptions::NONE);

        // Assert
        $this->assertNotSame($holder, $result);
        $this->assertEquals(TenantLoginProviderAccountLinkPolicyOptions::NONE, $result->accountLinkPolicy()->value());
    }
    public function testChangedAccountLinkPolicy(): void
    {
        // Arrange
        $holder = new ImplWithTenantLoginProviderAccountLinkPolicyAccessorUnitTest()->withAccountLinkPolicy(TenantLoginProviderAccountLinkPolicyOptions::NONE);
        $original = $holder->withAccountLinkPolicy(TenantLoginProviderAccountLinkPolicyOptions::NONE);
        $same = $holder->withAccountLinkPolicy(TenantLoginProviderAccountLinkPolicyOptions::NONE);
        $modified = $holder->withAccountLinkPolicy(TenantLoginProviderAccountLinkPolicyOptions::VERIFIED_EMAIL);

        // Act
        $withSame = $original->isAccountLinkPolicyChanged($same);
        $withDiferent = $original->isAccountLinkPolicyChanged($modified);

        // Assert
        $this->assertFalse($withSame);
        $this->assertTrue($withDiferent);
    }
}
class ImplWithTenantLoginProviderAccountLinkPolicyAccessorUnitTest
{
    use TenantLoginProviderAccountLinkPolicyAccessor;
}
